ALTER TABLE public.item_catalog
  ADD CONSTRAINT item_catalog_purpose_check CHECK (purpose IN ('animal_product', 'artisan', 'bouquet', 'crop', 'dish', 'fertilizer', 'fish', 'flower', 'fruit', 'gift', 'ingredient', 'keepsake', 'livestock_feed', 'pet_food', 'seed', 'sprinkler', 'stationery', 'tool', 'tree_sapling')),
